def test_parse_config_with_not_unique_cell_names():
    from ta_attenuator.config_parser import ConfigParser
    from ta_attenuator.config_loader import WrongSyntaxInConfigurationFile
    from ta_attenuator.attenuators_pool import AttenuatorsPool
    from ta_attenuator.cells_pool import CellsPool
    with pytest.raises(WrongSyntaxInConfigurationFile) as e:
        att_pool = AttenuatorsPool()
        cell_pool = CellsPool()
        ConfigParser(CONFIG_NOT_UNIQUE_CELL_NAMES, att_pool, cell_pool)


def test_parse_config_with_references(config_parser_with_references):
    attenuators_number = 2
    cells_number = 3
    referenced_cell_name = 'ENB_1_CELL_1'
    rf_paths_in_referenced_cell = [1, 2]
    config_parser_with_references.load_cells()
    config_parser_with_references.load_attenuators()
    assert len(config_parser_with_references.attenuators_pool.attenuators_registry.items()) == attenuators_number
    assert len(config_parser_with_references.cells_pool.cells_registry.items()) == cells_number
    referenced_cell = config_parser_with_references.cells_pool.get_cell(referenced_cell_name)
    assert referenced_cell.cell_config_list[0]['rf_paths_at_attenuator'] == rf_paths_in_referenced_cell


