def test_load_attenuator_with_wrong_min_and_max_attenuation_values():
    from ta_attenuator.config_parser import ConfigParser
    from ta_attenuator.attenuators_pool import AttenuatorsPool
    from ta_attenuator.cells_pool import CellsPool
    att_pool = AttenuatorsPool()
    cell_pool = CellsPool()
    parser = ConfigParser(CONFIG_WRONG_MIN_AND_MAX_VALUES, att_pool, cell_pool)
    with pytest.raises(ValueError) as e:
        parser.load_attenuators()


