def test_load_and_get_attenuator(config_parser):
    from ta_attenuator.attenuators_impls.jfw import JfwAttenuator
    from ta_attenuator.attenuators_impls.hytem import HytemAttenuator
    from ta_attenuator.attenuators_impls.radiorack import RadioRackAttenuator
    config_parser.load_attenuators()
    att_jfw = config_parser.attenuators_pool.get_attenuator('JFW_168')
    att_hytem = config_parser.attenuators_pool.get_attenuator('HYTEM_170')
    att_radiorack = config_parser.attenuators_pool.get_attenuator('RadioRack08')
    assert isinstance(att_jfw, JfwAttenuator)
    assert isinstance(att_hytem, HytemAttenuator)
    assert isinstance(att_radiorack, RadioRackAttenuator)


